from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            for y,x in q:
                comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            r0=min(y for y,x in comp);r1=max(y for y,x in comp)
            c0=min(x for y,x in comp);c1=max(x for y,x in comp)
            depth={}
            for y,x in comp:
                col=grid[y][x]
                dep=min(y-r0,r1-y,x-c0,c1-x)
                depth.setdefault(col,[]).append(dep)
            # outer to inner by average distance from bounding-box edge
            colors=sorted(depth,key=lambda col:sum(depth[col])/len(depth[col]))
            mapping={col:colors[len(colors)-1-i] for i,col in enumerate(colors)}
            for y,x in comp: out[y][x]=mapping[grid[y][x]]
    return out

